local x=np.transpose(np.astype(np.arange(24,"int64"):reshape({2,3,4}),"int64"),{3,2,1})
local before=x:tolist()
local y=r:permuted(x,1)
deep(y.dtype,"int64","0/(2, 3, 4)/int64/transpose/0/copy dtype")
deep(y:tolist(),{{{2,15},{5,16},{8,22}},{{0,14},{7,18},{10,23}},{{1,13},{4,19},{9,21}},{{3,12},{6,17},{11,20}}},"0/(2, 3, 4)/int64/transpose/0/copy values")
